  automations: [
  {
    "id": "auto-01",
    "name": "Deal Won -> Auto Create Project & Kickoff Tasks",
    "trigger": "deal_won",
    "triggerLabel": "When Deal is moved to \"Closed Won\"",
    "conditions": [
      {
        "field": "deal.amount",
        "operator": "greater_than",
        "value": "50000"
      }
    ],
    "actions": [
      {
        "type": "create_project",
        "label": "Create new Onboarding Project in Portfolio"
      },
      {
        "type": "create_task",
        "label": "Create Kickoff Meeting Task"
      },
      {
        "type": "notify_channel",
        "label": "Send Slack Announcement"
      }
    ],
    "isEnabled": true,
    "executionCount": 38,
    "lastRun": "2025-08-30T14:35:00Z"
  },
  {
    "id": "auto-02",
    "name": "High Severity Ticket -> Escalate to Principal Architect",
    "trigger": "ticket_created",
    "triggerLabel": "When Support Ticket is created with Priority \"Urgent\"",
    "conditions": [
      {
        "field": "ticket.priority",
        "operator": "equals",
        "value": "urgent"
      }
    ],
    "actions": [
      {
        "type": "assign_specialist",
        "label": "Assign Lead Solutions Architect automatically"
      },
      {
        "type": "send_sms_alert",
        "label": "Send PagerDuty On-Call Alert"
      }
    ],
    "isEnabled": true,
    "executionCount": 42,
    "lastRun": "2025-08-31T07:15:00Z"
  },
  {
    "id": "auto-03",
    "name": "Invoice Overdue > 7 Days -> Trigger AP Follow-up Sequence",
    "trigger": "invoice_overdue",
    "triggerLabel": "When Invoice status changes to \"Overdue\"",
    "conditions": [
      {
        "field": "invoice.total",
        "operator": "greater_than",
        "value": "10000"
      }
    ],
    "actions": [
      {
        "type": "update_account_status",
        "label": "Flag Account Health"
      },
      {
        "type": "send_email_template",
        "label": "Send Automated Payment Reminder"
      }
    ],
    "isEnabled": true,
    "executionCount": 19,
    "lastRun": "2025-08-24T09:00:00Z"
  },
  {
    "id": "auto-04",
    "name": "Project Milestone Completed -> Notify Client & Trigger Billing",
    "trigger": "milestone_completed",
    "triggerLabel": "When Project Milestone is marked as Completed",
    "conditions": [
      {
        "field": "project.budget",
        "operator": "greater_than",
        "value": "100000"
      }
    ],
    "actions": [
      {
        "type": "send_client_update",
        "label": "Send Milestone Completion Report"
      },
      {
        "type": "draft_invoice",
        "label": "Draft Progress Billing Invoice"
      }
    ],
    "isEnabled": true,
    "executionCount": 65,
    "lastRun": "2025-08-28T18:00:00Z"
  }
],
